WFJ.Data.add("book", {
  ["5a1c1a21531411e2"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">GRADI DI TRUPPA DELL'ALLEANZA</H1><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank05\" align=\"left\"/><BR/>\n<P align=\"right\">Sergente Maggiore</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank04\" align=\"left\"/><BR/>\n<P align=\"right\">Sergente Capo</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank03\" align=\"left\"/><BR/>\n<P align=\"right\">Sergente</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank02\" align=\"left\"/><BR/>\n<P align=\"right\">Caporale</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank01\" align=\"left\"/><BR/>\n<P align=\"right\">Soldato</P><BR/><BR/>\n</BODY>\n</HTML>", "." },
  ["5a25de616d8a7488"] = { "Gli stregoni demoniaci fecero piovere infernali roventi che si schiantarono come meteore dell'inferno sulle aggraziate guglie dei templi di Kalimdor. Una schiera di assassini ardenti e sanguinari, noti come Demoni Guardiani, marciò per i campi di Kalimdor, massacrando chiunque incontrasse sul suo cammino. Branchi di vilsegugi demoniaci e selvaggi devastarono le campagne senza incontrare resistenza. Benché i coraggiosi guerrieri kaldorei accorressero a difendere la loro antica patria, furono costretti a cedere terreno, palmo a palmo, davanti alla furia dell'assalto della Legione.", "." },
  ["5a2b2963061de6ce"] = { "Trascorsi le settimane successive spostandomi da un luogo all'altro, senza mai trattenermi per paura dei Cavalieri. Ora sono nella città abbandonata di Collecorvo, nascosto come sempre. Non posso affrontare il potere che hanno usato contro la moglie di Sven, e so che cerca ancora la Falce per tutta ⟦Duskwood=Boscovespro⟧. Per me è perduta, e ne ringrazio la Luce, perché se l'avessi tenuta so che mi avrebbero trovato. Anche ora, nel profondo del cuore, so che mi troveranno.\n\nSono così stanco.", "." },
  ["5a7492ba929a62cc"] = { "Aman'Thul, il Sommo Padre del Pantheon, concesse una parte del suo potere cosmico all'enorme drago di bronzo Nozdormu. Il Sommo Padre affidò a Nozdormu il compito di custodire il tempo stesso e di vigilare sui sentieri sempre mutevoli del fato e del destino. Lo stoico e onorevole Nozdormu divenne noto come il Senza Tempo.", "." },
  ["5a8d47138fa0b87e"] = { "Mentre l'impero cresceva ed espandeva i suoi confini verso nuove terre, anche i giovani maghi si sparsero nelle terre del sud. Con i loro poteri mistici, i maghi proteggevano i loro fratelli dalle creature selvagge di quelle terre e resero possibile costruire nuove città stato in mezzo alle terre selvagge. Eppure, man mano che i loro poteri crescevano, i maghi divennero sempre più vanitosi e isolati dal resto della società.", "." },
  ["5ac1739f61f20601"] = { "Ecco le specifiche del pistone:\n\nLunghezza: 32 WW\nLarghezza: 12 WW\nPeso: da 23.5 IBG a 25.5 IBG\nConduzione: 70 TC\nResistenza al taglio: 98 o superiore\nIndice di combobulazione: \"Super robusto\" o superiore\n\nNel caso avessi dimenticato le unità di misura gnomesche:\nWW = \"Whisker Width\" (spessore di un baffo)\nIBG = \"Itty-Bitty Grams\" (grammi piccini piccini)\nTC = \"Toe Curls\" (arricciamenti di alluce)", "." },
  ["5ada4409122745e9"] = { "Sapendo che Kil'jaeden non avrebbe gradito il suo fallimento nel distruggere il Trono di Ghiaccio, Illidan fuggì nella sterile dimensione nota come ⟦Outland=Terre Esterne⟧: gli ultimi resti di Draenor, l'antico mondo natale degli orchi. Lì intendeva sfuggire all'ira di Kil'jaeden e pianificare le sue prossime mosse.", "." },
})
